def safe_slug_filename(name, max_len):
    out = []
    prev_dash = False
    for c in name.lower():
        if c.isalnum():
            out.append(c)
            prev_dash = False
        else:
            if not prev_dash:
                out.append("-")
            prev_dash = True
    slug = "".join(out).strip("-")
    slug = slug[:max_len]
    slug = slug.rstrip("-")
    return slug

def count_specific_weekday_between(date1, date2, weekday):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    def weekday_of_ordinal(o):
        return (o + 5) % 7
    o1 = ordinal(date1)
    o2 = ordinal(date2)
    total_days = o2 - o1 + 1
    full_weeks = total_days // 7
    remainder = total_days % 7
    count = full_weeks
    start_weekday = weekday_of_ordinal(o1)
    for i in range(remainder):
        if (start_weekday + i) % 7 == weekday:
            count += 1
    return count

