def is_valid_ipv4_cidr(s):
    if s.count('/') != 1:
        return False
    ip, prefix = s.split('/')
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    if not prefix.isdigit():
        return False
    if len(prefix) > 1 and prefix[0] == '0':
        return False
    return 0 <= int(prefix) <= 32

def is_valid_hex_color_short(s):
    if len(s) != 4 or s[0] != '#':
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s[1:])

def is_unimodal(lst):
    n = len(lst)
    if n < 3:
        return False
    i = 0
    while i + 1 < n and lst[i] < lst[i + 1]:
        i += 1
    if i == 0 or i == n - 1:
        return False
    while i + 1 < n and lst[i] > lst[i + 1]:
        i += 1
    return i == n - 1

