def previous_day(date):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    if d > 1:
        return (y, m, d-1)
    m -= 1
    if m < 1:
        return (y-1, 12, 31)
    return (y, m, dim(y, m))

def most_frequent_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = lst[0]
    best_count = counts[lst[0]]
    for x in lst:
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

