def is_valid_uk_postcode_simplified(s):
    if s.count(' ') != 1:
        return False
    outward, inward = s.split(' ')
    if not (2 <= len(outward) <= 4):
        return False
    if not outward[0].isalpha() or not outward.isalnum():
        return False
    if len(inward) != 3:
        return False
    return inward[0].isdigit() and inward[1].isalpha() and inward[2].isalpha()

def group_consecutive(lst):
    if not lst:
        return []
    result = []
    prev = lst[0]
    count = 1
    for x in lst[1:]:
        if x == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = x
            count = 1
    result.append([prev, count])
    return result

