def time_zone_shift(time_str, hour_offset):
    h, m = time_str.split(':')
    total = int(h)*60 + int(m) + hour_offset*60
    day_offset = total // 1440
    rem = total % 1440
    return (day_offset, f'{rem//60:02d}:{rem%60:02d}')

def count_happy_numbers_in_range(a, b):
    def is_happy(n):
        seen = set()
        while n != 1 and n not in seen:
            seen.add(n)
            n = sum(int(d) ** 2 for d in str(n))
        return n == 1
    return sum(1 for x in range(a, b + 1) if is_happy(x))

def is_valid_temperature_reading(s):
    if len(s) < 2:
        return False
    unit = s[-1]
    if unit not in ('C', 'F'):
        return False
    num_part = s[:-1]
    if not num_part:
        return False
    idx = 1 if num_part[0] in '+-' else 0
    rest = num_part[idx:]
    if not rest or rest.startswith('.') or rest.endswith('.'):
        return False
    if rest.count('.') > 1:
        return False
    if not rest.replace('.', '').isdigit():
        return False
    return True

def pad_to_length(lst, n, pad):
    if len(lst) >= n:
        return lst[:n]
    return lst + [pad] * (n - len(lst))

def last_index_of_char(s, ch):
